package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class ZipArchiveEntry_setName_TriageGen1Test {

    @Test
    public void testSetNameSuccess() throws Exception {
        // Since setName is protected, we use reflection to access it for testing purposes
        ZipArchiveEntry entry = new ZipArchiveEntry("originalName");
        String newName = "newName.txt";

        Method setNameMethod = ZipArchiveEntry.class.getDeclaredMethod("setName", String.class);
        setNameMethod.setAccessible(true);

        setNameMethod.invoke(entry, newName);

        assertEquals("The name should be updated to the new value", newName, entry.getName());
    }






}

